function toE164(value) {
  const raw = String(value ?? '').trim();
  const digits = raw.replace(/\D/g, '');
  const nanp = (ten) => /^[2-9]\d{2}[2-9]\d{6}$/.test(ten);
  if (!raw) return '';
  if (raw.startsWith('+')) {
    if (digits.length < 8 || digits.length > 15) return '';
    if (digits.startsWith('1')) {
      return digits.length === 11 && nanp(digits.slice(1)) ? `+${digits}` : '';
    }
    return `+${digits}`;
  }
  if (digits.length === 10 && nanp(digits)) return `+1${digits}`;
  if (digits.length === 11 && digits.startsWith('1') && nanp(digits.slice(1))) return `+${digits}`;
  return '';
}

const payload = $json.body ?? $json;
const cliente = payload.cliente ?? {};
const event = payload.event ?? '';
const firstName = String(cliente.nome ?? '').trim().split(/\s+/)[0] || 'there';
const shortAddress = String(cliente.endereco_formatado ?? '').trim() || 'your address';
const etaMinutes = Number(payload.eta?.minutos);
const etaTime = String(payload.eta?.chegada_local ?? '').trim();
const hasEta = Number.isFinite(etaMinutes) && etaMinutes >= 0 && Boolean(etaTime);
const isTechnicalVisit = event === 'technical_visit_open_route';

let smsBody;
if (hasEta) {
  smsBody = isTechnicalVisit
    ? `Hi ${firstName}, our team is on the way for your technical visit at ${shortAddress}. Estimated arrival: about ${etaMinutes} minutes (around ${etaTime}). — CC Shower`
    : `Hi ${firstName}, our installation team is on the way to ${shortAddress}. Estimated arrival: about ${etaMinutes} minutes (around ${etaTime}). — CC Shower`;
} else {
  smsBody = isTechnicalVisit
    ? `Hi ${firstName}, our team is heading to your address for your technical visit and will arrive shortly. — CC Shower`
    : `Hi ${firstName}, our installation team is heading to your address and will arrive shortly. — CC Shower`;
}

return [{
  json: {
    event,
    os_id: payload.os_id ?? null,
    telefone: toE164(cliente.telefone),
    sms_body: smsBody,
  },
}];
